  (1, 'Alliance for Biodiversity and Conservation', 'ABC', 'Together for All Life.', 'ABC is a proposed youth-led initiative connecting young people and communities with biodiversity through environmental learning, citizen science, research and conservation action.', null, null, '{"forest":"#173D32","evergreen":"#245443","sage":"#A8B99B","ivory":"#F7F7F0","earth":"#795C43","charcoal":"#202923"}'::jsonb, 'ABC | Alliance for Biodiversity and Conservation', 'ABC connects young people and communities with biodiversity through environmental learning, citizen science, research and meaningful conservation action. Together for All Life.', '{"src":"/images/photos/elephants-family.jpg","alt":"An African bush elephant walking along a track through green bush with her young calf","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, '', '', '', '', '[]'::jsonb, 'A proposed youth-led initiative connecting young people and communities with biodiversity through learning, citizen science, research and conservation action.', '© {year} ABC — Alliance for Biodiversity and Conservation. All rights reserved.', true, 'Field notes, occasionally', 'Receive occasional updates on ABC''s proposed Nature Labs, research and ways to take part. We only use your email address for these updates.', 'Get Involved', '/get-involved', false)
