insert into public.homepage_sections (id, type, content, is_visible, sort_order) values
  ('c7024bd2-3b01-4e22-a53c-10ba8d5827ba', 'hero', '{"anchor":"","eyebrow":"Alliance for Biodiversity and Conservation","headline":"Together for All Life.","text":"We connect young people and communities with biodiversity through environmental learning, citizen science, research and meaningful conservation action.","primary":{"label":"Explore the living atlas","href":"/explorer"},"secondary":{"label":"Get Involved","href":"/get-involved"},"experience":"3d","theme":"auto","sound":true,"chapters":[{"title":"Discover.","text":"Every landscape is full of life. Learning to notice it is where conservation begins."},{"title":"Understand.","text":"Careful observation, shared between young people and communities, becomes knowledge."},{"title":"Protect.","text":"Understanding leads to action that communities choose, own and sustain."}],"hotspots":[{"title":"Forest canopy","text":"Mountain forests catch rain and mist and release water slowly to everything downstream.","zone":"canopy","link":{"label":"Montane rainforest","href":"/explorer#montane-rainforest"}},{"title":"Hills and farmland","text":"Most everyday biodiversity lives close to home: in fields, gardens and school grounds.","zone":"hills","link":{"label":"Hills and farmland","href":"/explorer#hills-and-farmland"}},{"title":"Wetland","text":"Marshes store and clean water, and shelter cranes, kingfishers and many other species.","zone":"wetland","link":{"label":"Wetlands and marshes","href":"/explorer#wetlands-and-marshes"}},{"title":"Open water","text":"Lakes and rivers connect every habitat in the landscape.","zone":"water","link":{"label":"Explore the atlas","href":"/explorer"}}],"mode":"slideshow","interval":8,"slides":[{"image":{"src":"/images/photos/elephants-family.jpg","alt":"An African bush elephant walking along a track through green bush with her young calf","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"},"visible":true},{"image":{"src":"/images/photos/grey-crowned-crane.jpg","alt":"A Grey Crowned Crane with its golden crest walking at the edge of shallow water","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"},"visible":true},{"image":{"src":"/images/photos/rugezi-wetland.jpg","alt":"Channels of water winding through the green Rugezi wetland beneath rolling hills","credit":"Bisoke, CC BY-SA 4.0, via Wikimedia Commons"},"visible":true},{"image":{"src":"/images/photos/mountain-gorilla.jpg","alt":"A mountain gorilla sitting among green leaves in Volcanoes National Park, Rwanda","credit":"Emmanuel Kwizera, CC BY-SA 4.0, via Wikimedia Commons"},"visible":true},{"image":{"src":"/images/photos/youth-tree-planting.jpg","alt":"Young people kneeling together to plant seedlings in Rwanda","credit":"Germain92, CC BY-SA 4.0, via Wikimedia Commons"},"visible":true}]}'::jsonb, true, 1),
  ('8981792c-f46c-44bc-a4e9-e574a9221a74', 'image_text', '{"anchor":"","eyebrow":"Who we are","heading":"Conservation Begins With Understanding.","body":"<p>Biodiversity is protected most effectively by the people who live alongside it. ABC, the Alliance for Biodiversity and Conservation, is a proposed youth-led initiative that helps young people and communities discover the species and ecosystems around them, study them with care, and act on what they learn.</p><p>Curiosity becomes commitment when people can observe nature first-hand, record what they see and contribute to real ecological knowledge. Our approach links environmental learning with citizen science, community research and practical conservation, so that understanding leads directly to action.</p>","image":{"src":"/images/photos/grey-crowned-crane-wetland.jpg","alt":"A Grey Crowned Crane standing in tall wetland grasses","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"},"image_position":"left","variant":"light","badge":"","link":{"label":"About ABC","href":"/about"}}'::jsonb, true, 2),
  ('a28fade9-d028-4479-a0c0-dcd1e4f911d1', 'atlas', '{"anchor":"","eyebrow":"The living atlas","heading":"Cross a country in a single line","intro":"From the shore of Lake Kivu, over mountain rainforest and cultivated hills, through valley wetlands to the eastern savanna. Choose a habitat to see how it works and who lives there.","note":"Educational reference information. These are not ABC field observations.","link":{"label":"Open the Biodiversity Explorer","href":"/explorer"}}'::jsonb, true, 3),
  ('7f883602-d807-4652-a86e-7b6adff5026a', 'cards', '{"anchor":"","eyebrow":"Our approach","heading":"Five interconnected activities","intro":"Each activity strengthens the others, moving people from their first encounters with nature towards lasting stewardship.","layout":"icon","columns":"5","background":"white","items":[{"icon":"sprout","title":"Nature Learning","text":"Hands-on environmental learning that helps children and young people recognise local species, habitats and ecological relationships.","image":null,"link":{"label":"Learn more","href":"/our-approach#nature-learning"}},{"icon":"binoculars","title":"Citizen Science","text":"Structured observation and recording of birds, plants and insects, so that community members contribute data that supports conservation.","image":null,"link":{"label":"Learn more","href":"/our-approach#citizen-science"}},{"icon":"microscope","title":"Community Research","text":"Locally led investigations into questions that matter to communities, supported by mentors and sound scientific methods.","image":null,"link":{"label":"Learn more","href":"/our-approach#community-research"}},{"icon":"trees","title":"Conservation Action","text":"Practical, community-owned responses such as habitat restoration and awareness activities, guided by evidence.","image":null,"link":{"label":"Learn more","href":"/our-approach#conservation-action"}},{"icon":"camera","title":"Conservation Storytelling","text":"Sharing what we learn through writing, photography and film to inspire wider care for biodiversity.","image":null,"link":{"label":"Learn more","href":"/our-approach#conservation-storytelling"}}]}'::jsonb, true, 4),
  ('2facde60-3142-41b0-affc-c3588e4c8058', 'steps', '{"anchor":"","eyebrow":"Research to action","heading":"From curiosity to conservation","intro":"A simple pathway guides every ABC activity, so that what people learn becomes knowledge they can use, act on and share. Choose a stage to see what happens there.","background":"forest","style":"pathway","items":[{"icon":"book-open","title":"Learn","text":"Discover local species, habitats and the relationships that connect them.","activities":"Guided nature walks\nSpecies identification sessions\nLearning from local knowledge holders","leads_to":"Knowing what to look for makes careful observation possible."},{"icon":"binoculars","title":"Observe","text":"Watch, record and document nature carefully and consistently.","activities":"Repeated counts at the same site\nField notebooks and photographs\nShared recording methods","leads_to":"Patterns in what is recorded raise questions worth investigating."},{"icon":"search","title":"Investigate","text":"Ask questions and gather evidence through community-led research.","activities":"Choosing a question that matters locally\nPlanning a simple, sound method\nCollecting evidence with mentors","leads_to":"Evidence has to be interpreted before it can guide decisions."},{"icon":"lightbulb","title":"Understand","text":"Interpret findings and connect them to local realities and knowledge.","activities":"Discussing results together\nComparing findings with local knowledge\nBeing honest about what is still uncertain","leads_to":"Shared understanding shows where practical action would help most."},{"icon":"sprout","title":"Act","text":"Turn understanding into practical, community-owned conservation.","activities":"Habitat restoration\nAwareness activities\nChanges agreed and led by the community","leads_to":"What worked, and what did not, is worth telling others."},{"icon":"megaphone","title":"Share","text":"Communicate what we learn to inform and inspire others.","activities":"Community presentations\nWriting, photography and film\nPublishing results openly","leads_to":"Stories bring new people in, and the cycle begins again with learning."}]}'::jsonb, true, 5),
  ('b03461ee-3ece-40be-a908-fa2681251126', 'image_text', '{"anchor":"","eyebrow":"Community Nature Labs","heading":"Learning From the Natural World Around Us.","body":"<p>ABC proposes to establish Community Nature Learning and Citizen Science Labs: welcoming, practical spaces where children, young people and community members learn about biodiversity, take part in structured observation and contribute to local research.</p><p>The first phase is a proposed six-month pilot at two sites in Rwanda. It is designed to test the Nature Lab model, learn from participants and build the evidence needed to grow responsibly.</p>","image":{"src":"/images/photos/rwanda-hills-sunrise.jpg","alt":"Sunrise over layered forested hills in Nyungwe, Rwanda","credit":"Jonkmania, CC BY-SA 4.0, via Wikimedia Commons"},"image_position":"right","variant":"feature","badge":"Proposed six-month pilot · Two sites in Rwanda","link":{"label":"Discover Nature Labs","href":"/nature-labs"}}'::jsonb, true, 6),
  ('bc7f9e01-57eb-47b1-a989-43197a0ca219', 'programmes', '{"anchor":"","eyebrow":"Programme areas","heading":"Building a long-term movement","intro":"Five proposed programme areas set out how ABC intends to grow beyond the pilot. They are long-term ambitions that will be developed in stages.","featured_only":false,"link":{"label":"View all programmes","href":"/programmes"}}'::jsonb, true, 7),
  ('8fb4bb78-ecda-4468-acc2-d960813e4860', 'statistics', '{"anchor":"","eyebrow":"Six-month pilot targets","heading":"What the proposed pilot aims to achieve","intro":"These figures are proposed targets for ABC''s initial six-month Rwanda pilot. They will be replaced with verified outcomes as the work progresses.","note":"Proposed targets for the six-month pilot. These are not achieved results.","status_filter":"all","show_legend":true}'::jsonb, true, 8),
  ('88f93f15-7eef-47a5-aea6-d3cd3f2a32cd', 'milestones', '{"anchor":"","eyebrow":"Planned stages","heading":"How the proposed pilot would unfold","intro":"","note":"These stages are planned. Each will be marked as in progress or done only when that is true."}'::jsonb, true, 9),
  ('511a8b4f-14fa-409f-a546-afe743966ce7', 'stories', '{"anchor":"","eyebrow":"Stories & insights","heading":"Notes from the natural world","intro":"Updates, explainers and perspectives on biodiversity, young people and community conservation.","count":3,"featured_only":false,"link":{"label":"All stories","href":"/stories"}}'::jsonb, true, 10),
  ('1906492d-4242-4ebd-abba-2da5c340b4a5', 'partners', '{"anchor":"","eyebrow":"Working together","heading":"Partners and collaboration","intro":"Organisations that have formally partnered with ABC.","relationship":"confirmed","note":"","empty_text":"ABC is at the proposal stage and has no confirmed partners yet. We would welcome conversations with schools, research institutions, conservation organisations and funders who share this aim.","link":{"label":"Explore collaboration","href":"/partners"}}'::jsonb, true, 11),
  ('9977d2bd-8697-482d-ae32-4f45f5b8d645', 'cards', '{"anchor":"","eyebrow":"Get involved","heading":"There is a place for you in this work","intro":"Whether you are a young person curious about nature, a researcher, an educator or an organisation, we would welcome your interest.","layout":"image","columns":"5","background":"ivory","items":[{"icon":"hand-heart","title":"Volunteer","text":"Offer your time and skills to help prepare and run nature learning activities.","image":{"src":"/images/photos/youth-seedlings-group.jpg","alt":"A group of young people holding tree seedlings during a planting campaign","credit":"Atwijukirenaomi, CC BY-SA 4.0, via Wikimedia Commons"},"link":{"label":"Volunteer","href":"/get-involved#apply"}},{"icon":"binoculars","title":"Become a youth researcher","text":"Learn field methods, record biodiversity and investigate questions that matter locally.","image":{"src":"/images/photos/akagera-waterbirds.jpg","alt":"Cormorants perched on small islands in calm water fringed by papyrus in Akagera National Park","credit":"John Cooke, CC BY 2.0, via Wikimedia Commons"},"link":{"label":"Express interest","href":"/get-involved#apply"}},{"icon":"handshake","title":"Partner with ABC","text":"Explore an institutional partnership to strengthen youth-led conservation.","image":{"src":"/images/photos/community-planting-kivu.jpg","alt":"A young man planting a seedling on a hillside above Lake Kivu while others work nearby","credit":"Rogerirakoze, CC BY 4.0, via Wikimedia Commons"},"link":{"label":"Start a conversation","href":"/contact"}},{"icon":"sprout","title":"Support community Nature Labs","text":"Help bring the proposed Nature Lab pilot to life in two Rwandan communities.","image":{"src":"/images/photos/youth-tree-planting.jpg","alt":"Young people kneeling together to plant seedlings in Rwanda","credit":"Germain92, CC BY-SA 4.0, via Wikimedia Commons"},"link":{"label":"Find out how","href":"/nature-labs"}},{"icon":"microscope","title":"Collaborate on research","text":"Work with young researchers and communities on ecological questions.","image":{"src":"/images/photos/rugezi-wetland.jpg","alt":"Channels of water winding through the green Rugezi wetland beneath rolling hills","credit":"Bisoke, CC BY-SA 4.0, via Wikimedia Commons"},"link":{"label":"Collaborate","href":"/get-involved#apply"}}]}'::jsonb, true, 12),
  ('e9ebf60c-1d4b-4dfc-a2af-1f24a5cd0c24', 'cta', '{"anchor":"","eyebrow":"Together for All Life","heading":"Help shape ABC from the beginning","text":"ABC is at an early stage. If you share our commitment to biodiversity and to young people, we would welcome a conversation.","primary":{"label":"Contact us","href":"/contact"},"secondary":{"label":"Get involved","href":"/get-involved"},"image":{"src":"/images/photos/lake-kivu.jpg","alt":"Forested shoreline and calm water of Lake Kivu, Rwanda","credit":"Muhirehussein12, CC BY-SA 4.0, via Wikimedia Commons"}}'::jsonb, true, 13)
insert into public.pages (status, seo_title, seo_description, slug, title, hero_eyebrow, description, hero_image, is_system, sections, id) values
  ('published', '', '', 'about', 'About ABC', 'Alliance for Biodiversity and Conservation', 'A proposed youth-led initiative connecting young people and communities with the biodiversity around them.', '{"src":"/images/photos/nyungwe-forest.jpg","alt":"Montane rainforest trees in Nyungwe Forest National Park, Rwanda","credit":"Brian Harries, CC BY 2.0, via Wikimedia Commons"}'::jsonb, true, '[{"id":"7865a474-5476-4784-aa60-545c627c6b5c","type":"rich_text","visible":true,"data":{"anchor":"","eyebrow":"Who we are","heading":"A youth-led alliance for all life","body":"<p>ABC, the Alliance for Biodiversity and Conservation, is a proposed youth-led initiative dedicated to connecting young people and communities with the biodiversity around them.</p><p>We bring together environmental learning, citizen science, community research and conservation action, so that the people who live closest to nature are equipped to understand it, study it and protect it.</p><p>ABC is in its early stages. Our first proposed step is a six-month pilot of Community Nature Learning and Citizen Science Labs at two sites in Rwanda.</p>","width":"narrow","background":"ivory"}},{"id":"fc6882ca-b5d8-465a-a993-eb22a11a7222","type":"statement","visible":true,"data":{"anchor":"","eyebrow":"Our purpose","text":"Empowering young people and communities through environmental learning, citizen science, research and collective action to protect biodiversity and sustain healthy ecosystems.","attribution":"","background":"forest"}},{"id":"b81d06eb-18a2-4bfb-aa8b-7f6366f5dc63","type":"cards","visible":true,"data":{"anchor":"","eyebrow":"Vision and mission","heading":"Where we are heading","intro":"","layout":"icon","columns":"2","background":"white","items":[{"icon":"eye","title":"Our vision","text":"A world where young people and communities actively contribute to a thriving, biodiverse planet.","image":null,"link":{"label":"","href":""}},{"icon":"compass","title":"Our mission","text":"To connect, equip and mobilise young people and communities to understand biodiversity, generate ecological knowledge and take meaningful conservation action.","image":null,"link":{"label":"","href":""}}]}},{"id":"cde8c591-967c-4341-a185-21d9160090d9","type":"image_text","visible":true,"data":{"anchor":"","eyebrow":"Our story","heading":"Starting with understanding","body":"<p>ABC begins from a simple observation: many young people grow up surrounded by remarkable biodiversity, yet have few opportunities to explore it, study it or take part in decisions about its future.</p><p>The initiative proposes to change that by creating practical spaces for learning and discovery, linking participants with mentors and researchers, and supporting community-led conservation. Rather than starting large, ABC intends to begin with a carefully designed pilot, learn from it and grow responsibly.</p><p>We look forward to writing the next chapters together with the communities, young people and institutions who join us.</p>","image":{"src":"/images/photos/youth-tree-planting.jpg","alt":"Young people kneeling together to plant seedlings in Rwanda","credit":"Germain92, CC BY-SA 4.0, via Wikimedia Commons"},"image_position":"right","variant":"light","badge":"","link":{"label":"","href":""}}},{"id":"0258440a-243d-487a-a128-a8920f786592","type":"cards","visible":true,"data":{"anchor":"","eyebrow":"Core values","heading":"What guides us","intro":"Seven values shape how ABC works with young people, communities and partners.","layout":"icon","columns":"4","background":"sage","items":[{"icon":"leaf","title":"Biodiversity","text":"We value every form of life and the ecosystems that sustain them.","image":null,"link":{"label":"","href":""}},{"icon":"users","title":"Community ownership","text":"Communities lead, shape and own conservation work in their places.","image":null,"link":{"label":"","href":""}},{"icon":"sprout","title":"Youth leadership","text":"Young people are leaders and decision-makers today, not only in the future.","image":null,"link":{"label":"","href":""}},{"icon":"microscope","title":"Scientific curiosity","text":"We ask questions, gather evidence and learn from what we find.","image":null,"link":{"label":"","href":""}},{"icon":"handshake","title":"Collaboration","text":"We achieve more by working with others across disciplines and sectors.","image":null,"link":{"label":"","href":""}},{"icon":"target","title":"Action","text":"Knowledge should lead to practical and meaningful conservation outcomes.","image":null,"link":{"label":"","href":""}},{"icon":"heart-handshake","title":"Inclusion","text":"Everyone belongs in the work of protecting nature, whatever their background.","image":null,"link":{"label":"","href":""}}]}},{"id":"81a43d78-fd2d-43a8-a5a8-6d705e6ef270","type":"steps","visible":true,"data":{"anchor":"","eyebrow":"Our approach","heading":"Learn, observe, investigate, understand, act, share","intro":"Our approach turns curiosity into evidence and evidence into community-led action.","background":"white","items":[{"icon":"book-open","title":"Learn","text":"Discover local species, habitats and the relationships that connect them.","activities":"Guided nature walks\nSpecies identification sessions\nLearning from local knowledge holders","leads_to":"Knowing what to look for makes careful observation possible."},{"icon":"binoculars","title":"Observe","text":"Watch, record and document nature carefully and consistently.","activities":"Repeated counts at the same site\nField notebooks and photographs\nShared recording methods","leads_to":"Patterns in what is recorded raise questions worth investigating."},{"icon":"search","title":"Investigate","text":"Ask questions and gather evidence through community-led research.","activities":"Choosing a question that matters locally\nPlanning a simple, sound method\nCollecting evidence with mentors","leads_to":"Evidence has to be interpreted before it can guide decisions."},{"icon":"lightbulb","title":"Understand","text":"Interpret findings and connect them to local realities and knowledge.","activities":"Discussing results together\nComparing findings with local knowledge\nBeing honest about what is still uncertain","leads_to":"Shared understanding shows where practical action would help most."},{"icon":"sprout","title":"Act","text":"Turn understanding into practical, community-owned conservation.","activities":"Habitat restoration\nAwareness activities\nChanges agreed and led by the community","leads_to":"What worked, and what did not, is worth telling others."},{"icon":"megaphone","title":"Share","text":"Communicate what we learn to inform and inspire others.","activities":"Community presentations\nWriting, photography and film\nPublishing results openly","leads_to":"Stories bring new people in, and the cycle begins again with learning."}]}},{"id":"6bff34c5-9519-4bf5-a835-5ccd3c6d91cd","type":"team","visible":true,"data":{"anchor":"","eyebrow":"People","heading":"Our team","intro":"The people building ABC."}},{"id":"332887e6-ec5e-4336-a270-494eea8c604e","type":"cta","visible":true,"data":{"anchor":"","eyebrow":"Get involved","heading":"Join us in protecting all life","text":"Volunteer, become a youth researcher, collaborate on research or explore a partnership with ABC.","primary":{"label":"Get involved","href":"/get-involved"},"secondary":{"label":"Contact us","href":"/contact"},"image":{"src":"/images/photos/youth-seedlings-group.jpg","alt":"A group of young people holding tree seedlings during a planting campaign","credit":"Atwijukirenaomi, CC BY-SA 4.0, via Wikimedia Commons"}}}]'::jsonb, '3fbd94c5-eaa4-4cf5-a1dd-207d14463d7d'),
  ('published', '', '', 'our-approach', 'Our Approach', 'What we do', 'Five interconnected activities that move people from learning about nature to lasting conservation action.', '{"src":"/images/photos/akagera-waterbirds.jpg","alt":"Cormorants perched on small islands in calm water fringed by papyrus in Akagera National Park","credit":"John Cooke, CC BY 2.0, via Wikimedia Commons"}'::jsonb, true, '[{"id":"9d74a3ae-06f5-4e3e-a9d5-19264e0d4e26","type":"rich_text","visible":true,"data":{"anchor":"","eyebrow":"An integrated approach","heading":"Five activities, one pathway","body":"<p>ABC''s work is organised around five interconnected activities. Together they form a pathway that begins with curiosity and leads to communities generating knowledge and leading conservation in their own places.</p><p>The activities described here set out how ABC intends to work. They will be introduced first through the proposed six-month Rwanda pilot and refined based on what we learn.</p>","width":"narrow","background":"ivory"}},{"id":"4b6b5d2e-446a-44fe-ad7d-d52685045c26","type":"image_text","visible":true,"data":{"anchor":"nature-learning","eyebrow":"01 · Nature Learning","heading":"Discovering the living world nearby","body":"<p>Nature Learning introduces children, young people and community members to the biodiversity around them. Through guided walks, species identification, habitat exploration and practical activities, participants build the knowledge and confidence to notice and value nature.</p><ul><li>Outdoor, hands-on and age-appropriate learning</li><li>A focus on locally relevant species and ecosystems</li><li>Respect for local and indigenous knowledge</li></ul>","image":{"src":"/images/photos/youth-seedlings-group.jpg","alt":"A group of young people holding tree seedlings during a planting campaign","credit":"Atwijukirenaomi, CC BY-SA 4.0, via Wikimedia Commons"},"image_position":"right","variant":"light","badge":"","link":{"label":"","href":""}}},{"id":"597bd10c-65b2-419c-ac77-bc74dac77974","type":"image_text","visible":true,"data":{"anchor":"citizen-science","eyebrow":"02 · Citizen Science","heading":"Everyone can contribute to knowledge","body":"<p>Citizen science invites participants to observe and record nature systematically, from bird counts to plant and insect surveys. Using simple, consistent methods, community members can generate records that help track change and inform conservation.</p><ul><li>Structured observation and recording</li><li>Training in identification and data quality</li><li>Sharing records with wider biodiversity databases where appropriate</li></ul>","image":{"src":"/images/photos/grey-crowned-crane.jpg","alt":"A Grey Crowned Crane with its golden crest walking at the edge of shallow water","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"},"image_position":"left","variant":"sage","badge":"","link":{"label":"","href":""}}},{"id":"43aab971-dcd5-4f01-a926-fb59d0ad8259","type":"image_text","visible":true,"data":{"anchor":"community-research","eyebrow":"03 · Community Research","heading":"Questions that matter locally","body":"<p>Community Research supports young people and community members to design and carry out investigations into questions that matter to them, such as how a wetland is changing or which species depend on a local forest.</p><ul><li>Locally defined research questions</li><li>Mentoring from experienced researchers</li><li>Ethical, rigorous and practical methods</li></ul>","image":{"src":"/images/photos/rugezi-wetland.jpg","alt":"Channels of water winding through the green Rugezi wetland beneath rolling hills","credit":"Bisoke, CC BY-SA 4.0, via Wikimedia Commons"},"image_position":"right","variant":"light","badge":"","link":{"label":"","href":""}}},{"id":"e469f3ce-d574-4c1e-a1cf-9956d64b0856","type":"image_text","visible":true,"data":{"anchor":"conservation-action","eyebrow":"04 · Conservation Action","heading":"From evidence to stewardship","body":"<p>Conservation Action turns understanding into practical responses that communities own and sustain, such as habitat restoration, native tree planting, awareness activities and dialogue with local decision-makers.</p><ul><li>Actions guided by evidence gathered locally</li><li>Community ownership and long-term care</li><li>Collaboration with conservation authorities and organisations</li></ul>","image":{"src":"/images/photos/community-planting-kivu.jpg","alt":"A young man planting a seedling on a hillside above Lake Kivu while others work nearby","credit":"Rogerirakoze, CC BY 4.0, via Wikimedia Commons"},"image_position":"left","variant":"sage","badge":"","link":{"label":"","href":""}}},{"id":"39f2fb59-3b5a-4b29-a3b7-138157ef4881","type":"image_text","visible":true,"data":{"anchor":"conservation-storytelling","eyebrow":"05 · Conservation Storytelling","heading":"Sharing what we learn","body":"<p>Conservation Storytelling helps participants communicate their discoveries through writing, photography, film and community events. Stories carry knowledge beyond the field, inspire others and give young people a voice in conservation.</p><ul><li>Photography, writing and short film</li><li>Community exhibitions and presentations</li><li>Stories published on this website</li></ul>","image":{"src":"/images/photos/mountain-gorilla.jpg","alt":"A mountain gorilla sitting among green leaves in Volcanoes National Park, Rwanda","credit":"Emmanuel Kwizera, CC BY-SA 4.0, via Wikimedia Commons"},"image_position":"right","variant":"light","badge":"","link":{"label":"Read our stories","href":"/stories"}}},{"id":"9b50a392-ab01-4162-ab74-bb3a19c4783a","type":"steps","visible":true,"data":{"anchor":"research-to-action","eyebrow":"Research to action","heading":"How the activities connect","intro":"Every activity contributes to a single pathway from learning to sharing.","background":"white","items":[{"icon":"book-open","title":"Learn","text":"Discover local species, habitats and the relationships that connect them.","activities":"Guided nature walks\nSpecies identification sessions\nLearning from local knowledge holders","leads_to":"Knowing what to look for makes careful observation possible."},{"icon":"binoculars","title":"Observe","text":"Watch, record and document nature carefully and consistently.","activities":"Repeated counts at the same site\nField notebooks and photographs\nShared recording methods","leads_to":"Patterns in what is recorded raise questions worth investigating."},{"icon":"search","title":"Investigate","text":"Ask questions and gather evidence through community-led research.","activities":"Choosing a question that matters locally\nPlanning a simple, sound method\nCollecting evidence with mentors","leads_to":"Evidence has to be interpreted before it can guide decisions."},{"icon":"lightbulb","title":"Understand","text":"Interpret findings and connect them to local realities and knowledge.","activities":"Discussing results together\nComparing findings with local knowledge\nBeing honest about what is still uncertain","leads_to":"Shared understanding shows where practical action would help most."},{"icon":"sprout","title":"Act","text":"Turn understanding into practical, community-owned conservation.","activities":"Habitat restoration\nAwareness activities\nChanges agreed and led by the community","leads_to":"What worked, and what did not, is worth telling others."},{"icon":"megaphone","title":"Share","text":"Communicate what we learn to inform and inspire others.","activities":"Community presentations\nWriting, photography and film\nPublishing results openly","leads_to":"Stories bring new people in, and the cycle begins again with learning."}]}},{"id":"115526ce-7517-43fe-a918-6676cc365376","type":"cta","visible":true,"data":{"anchor":"","eyebrow":"Get involved","heading":"Join us in protecting all life","text":"Volunteer, become a youth researcher, collaborate on research or explore a partnership with ABC.","primary":{"label":"Get involved","href":"/get-involved"},"secondary":{"label":"Contact us","href":"/contact"},"image":{"src":"/images/photos/youth-seedlings-group.jpg","alt":"A group of young people holding tree seedlings during a planting campaign","credit":"Atwijukirenaomi, CC BY-SA 4.0, via Wikimedia Commons"}}}]'::jsonb, 'bbc69354-b3cf-41a4-a1cc-590c73ded80c'),
  ('published', '', '', 'nature-labs', 'Nature Labs', 'Community Nature Learning and Citizen Science Labs', 'A proposed model for community-based places of discovery, learning and research, beginning with a six-month pilot in Rwanda.', '{"src":"/images/photos/community-wetland-planting.jpg","alt":"Two people planting vegetation among green plants as part of wetland protection in Rwanda","credit":"Germain92, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, true, '[{"id":"a0043c0d-3025-495d-a7d5-f5653ff20c65","type":"image_text","visible":true,"data":{"anchor":"","eyebrow":"What is a Nature Lab?","heading":"A place to learn from the natural world","body":"<p>A Community Nature Learning and Citizen Science Lab, or Nature Lab, is a proposed community-based space where children, young people and community members come together to explore biodiversity, learn practical field skills and contribute to research.</p><p>A Nature Lab is less a building than a way of working: a local base, a nearby natural site, simple equipment, trained facilitators and a programme of regular activities shaped by the community.</p>","image":{"src":"/images/photos/youth-tree-planting.jpg","alt":"Young people kneeling together to plant seedlings in Rwanda","credit":"Germain92, CC BY-SA 4.0, via Wikimedia Commons"},"image_position":"right","variant":"light","badge":"Proposed model","link":{"label":"","href":""}}},{"id":"e27e79f3-8fac-4f83-afd7-c54b62f5b24b","type":"steps","visible":true,"data":{"anchor":"","eyebrow":"How the model works","heading":"A cycle of learning and action","intro":"Each proposed Nature Lab would follow a simple cycle that communities can adapt to their own setting.","background":"white","items":[{"icon":"users","title":"Engage","text":"Work with local leaders, schools and residents to agree on goals and a suitable site."},{"icon":"book-open","title":"Learn","text":"Run regular nature learning sessions for children and young people."},{"icon":"binoculars","title":"Observe","text":"Introduce structured citizen science recording of local species."},{"icon":"microscope","title":"Investigate","text":"Support youth researchers to carry out small community research projects."},{"icon":"sprout","title":"Act","text":"Plan practical conservation responses with the community."},{"icon":"megaphone","title":"Share","text":"Present findings to the community and share stories more widely."}]}},{"id":"ad86b9a4-78ca-46f4-a7a9-dc0c0393b10c","type":"cards","visible":true,"data":{"anchor":"","eyebrow":"Community participation","heading":"Built with and for communities","intro":"Nature Labs are designed to be shaped and owned by the people who take part in them.","layout":"icon","columns":"3","background":"ivory","items":[{"icon":"sprout","title":"Children and young people","text":"The heart of each Nature Lab, taking part in learning, observation and storytelling.","image":null,"link":{"label":"","href":""}},{"icon":"binoculars","title":"Youth researchers","text":"Older young people trained to lead observations and community research.","image":null,"link":{"label":"","href":""}},{"icon":"school","title":"Teachers and educators","text":"Partners in connecting Nature Lab activities with classroom learning.","image":null,"link":{"label":"","href":""}},{"icon":"users","title":"Community members","text":"Residents who help shape priorities, share knowledge and take part in action.","image":null,"link":{"label":"","href":""}},{"icon":"feather","title":"Local knowledge holders","text":"Elders and practitioners whose knowledge of the land enriches every activity.","image":null,"link":{"label":"","href":""}},{"icon":"graduation-cap","title":"Researchers and mentors","text":"Scientists and practitioners who offer guidance and help ensure rigour.","image":null,"link":{"label":"","href":""}}]}},{"id":"e00c93c1-dc3b-4a11-a225-836986a0f269","type":"cards","visible":true,"data":{"anchor":"","eyebrow":"Potential research themes","heading":"Questions we could explore together","intro":"Research themes will be agreed with each community. These are examples of potential areas of focus.","layout":"numbered","columns":"3","background":"white","items":[{"icon":"bird","title":"Birds and seasonal change","text":"Recording local bird diversity, including wetland species such as the Grey Crowned Crane.","image":null,"link":{"label":"","href":""}},{"icon":"droplets","title":"Wetland health","text":"Observing water, vegetation and wildlife to understand how wetlands are changing.","image":null,"link":{"label":"","href":""}},{"icon":"bug","title":"Pollinators and insects","text":"Surveying insects that support local farming and ecosystems.","image":null,"link":{"label":"","href":""}},{"icon":"trees","title":"Native plants and restoration","text":"Identifying native species and monitoring restoration efforts.","image":null,"link":{"label":"","href":""}},{"icon":"footprints","title":"People and wildlife","text":"Understanding relationships between communities and the wildlife around them.","image":null,"link":{"label":"","href":""}},{"icon":"sun","title":"Climate and local ecosystems","text":"Documenting local observations of seasonal and environmental change.","image":null,"link":{"label":"","href":""}}]}},{"id":"5089d403-a9c4-4133-a3a7-756b17dfaa6b","type":"image_text","visible":true,"data":{"anchor":"rwanda-pilot","eyebrow":"The Rwanda pilot","heading":"Starting small, learning carefully","body":"<p>ABC proposes a six-month pilot at two sites in Rwanda to test the Nature Lab model in practice. The pilot aims to engage children and young people in nature learning, train a group of youth researchers and support two community research projects.</p><p>The pilot sites have not yet been established. Their selection, design and activities will be developed together with communities and relevant institutions. Results will be shared openly on this website as the work progresses.</p>","image":{"src":"/images/photos/lake-kivu.jpg","alt":"Forested shoreline and calm water of Lake Kivu, Rwanda","credit":"Muhirehussein12, CC BY-SA 4.0, via Wikimedia Commons"},"image_position":"left","variant":"feature","badge":"Proposed · Six months · Two sites","link":{"label":"Collaborate on the pilot","href":"/get-involved#apply"}}},{"id":"a6ee214d-9d9e-46dd-ae38-b1558270e655","type":"nature_labs","visible":true,"data":{"anchor":"sites","eyebrow":"Nature Lab sites","heading":"Where Nature Labs are","intro":"","empty_text":"No Nature Labs have been established yet. The two proposed pilot sites will be chosen together with communities, and will appear here once they are agreed."}},{"id":"825529ed-5d8d-4f1d-ab10-bfc50f48f4c5","type":"cards","visible":true,"data":{"anchor":"start","eyebrow":"Taking part","heading":"How a community could host or join a Nature Lab","intro":"A Nature Lab does not need a permanent building. It needs people, a place to meet and somewhere nearby to observe nature.","layout":"numbered","columns":"4","background":"white","items":[{"title":"Start a conversation","text":"A school, youth group or community tells ABC about its interest and its local setting.","icon":"leaf","image":null,"link":{"label":"","href":""}},{"title":"Choose a place","text":"Together we identify a meeting place and a nearby natural site: a wetland edge, a woodland or a school garden.","icon":"leaf","image":null,"link":{"label":"","href":""}},{"title":"Agree priorities","text":"Community members decide what they most want to learn about and protect.","icon":"leaf","image":null,"link":{"label":"","href":""}},{"title":"Begin regular sessions","text":"Trained facilitators and young researchers start learning and recording activities.","icon":"leaf","image":null,"link":{"label":"","href":""}}]}},{"id":"059180db-294c-4c8b-acca-2cd31b19e9d3","type":"statistics","visible":true,"data":{"anchor":"","eyebrow":"Pilot targets","heading":"What the proposed pilot aims to achieve","intro":"Targets for the proposed six-month pilot. They will be updated with verified results.","note":"Proposed targets for the six-month pilot. These are not achieved results.","status_filter":"all"}},{"id":"f3f97d65-a127-42f5-aef7-57dd421544dd","type":"faq","visible":true,"data":{"anchor":"","eyebrow":"Questions","heading":"About the Nature Labs","items":[{"question":"Are the Nature Labs already operating?","answer":"Not yet. The Nature Labs are a proposed model. ABC plans to begin with a six-month pilot at two sites in Rwanda, and we will share progress here as it happens."},{"question":"Where will the pilot sites be?","answer":"The two pilot sites will be selected together with communities and relevant institutions in Rwanda. We will publish details once sites are confirmed."},{"question":"How can my organisation collaborate?","answer":"We would welcome conversations with schools, community groups, researchers and conservation organisations. Please use the form on our Get Involved page or contact us directly."}]}},{"id":"300be5cb-fd88-4c9b-ab08-2d437e261a43","type":"cta","visible":true,"data":{"anchor":"","eyebrow":"How to collaborate","heading":"Help bring Nature Labs to life","text":"We are looking for communities, educators, researchers and organisations who would like to help shape the pilot.","primary":{"label":"Express interest","href":"/get-involved#apply"},"secondary":{"label":"Contact us","href":"/contact"},"image":{"src":"/images/photos/akagera-waterbirds.jpg","alt":"Cormorants perched on small islands in calm water fringed by papyrus in Akagera National Park","credit":"John Cooke, CC BY 2.0, via Wikimedia Commons"}}}]'::jsonb, '849a92e6-d452-4b96-a49c-087ef8d43d7e'),
  ('published', '', '', 'programmes', 'Programmes', 'Programme areas', 'Five proposed long-term programme areas that describe how ABC intends to grow.', '{"src":"/images/photos/elephants-chobe.jpg","alt":"Two young African bush elephants walking together across a sandy riverbank","credit":"Diego Delso, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, true, '[{"id":"25f7eca3-cea3-4473-aee4-04cbf31c39cb","type":"rich_text","visible":true,"data":{"anchor":"","eyebrow":"Our ambitions","heading":"A long-term framework","body":"<p>ABC''s programme areas describe how the initiative intends to grow over time. They are proposed, long-term areas of work rather than fully operational programmes, and will be developed in stages, beginning with the Rwanda Nature Lab pilot.</p>","width":"narrow","background":"ivory"}},{"id":"513b55bf-52b0-466f-a340-7c274b5c9327","type":"programmes","visible":true,"data":{"anchor":"","eyebrow":"","heading":"Programme areas","intro":"","featured_only":false,"link":{"label":"","href":""}}},{"id":"d124ebbb-68b2-41eb-a52d-0ab3b84af7b3","type":"cta","visible":true,"data":{"anchor":"","eyebrow":"Get involved","heading":"Join us in protecting all life","text":"Volunteer, become a youth researcher, collaborate on research or explore a partnership with ABC.","primary":{"label":"Get involved","href":"/get-involved"},"secondary":{"label":"Contact us","href":"/contact"},"image":{"src":"/images/photos/youth-seedlings-group.jpg","alt":"A group of young people holding tree seedlings during a planting campaign","credit":"Atwijukirenaomi, CC BY-SA 4.0, via Wikimedia Commons"}}}]'::jsonb, 'f717aa83-4e26-4413-a2d1-d38baaedea8b'),
  ('published', '', '', 'stories', 'Stories & Media', 'Stories, research and field notes', 'Articles, research updates, field notes, photo stories and community perspectives from ABC.', '{"src":"/images/photos/grey-crowned-crane.jpg","alt":"A Grey Crowned Crane with its golden crest walking at the edge of shallow water","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, true, '[]'::jsonb, 'e0e90849-dd66-49b9-ad38-2fb14c2714b1'),
  ('published', '', '', 'explorer', 'The Living Atlas', 'Biodiversity Explorer', 'Travel across Rwanda''s landscapes, from lake shore to savanna, and meet some of the species that live there.', '{"src":"/images/photos/great-blue-turaco.jpg","alt":"A great blue turaco perched on a branch, showing its blue-green plumage and dark crest","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, true, '[{"id":"fde2d451-afac-4f61-ac21-ce1934e85319","type":"atlas","visible":true,"data":{"anchor":"","eyebrow":"Five habitats, one transect","heading":"Choose a habitat","intro":"The line below runs west to east across Rwanda. Each habitat sits at its own height and does its own work in the landscape.","note":"Educational reference information. These are not ABC field observations.","link":{"label":"","href":""}}},{"id":"6485e2a8-338d-4558-ac0e-da70aadd6770","type":"species","visible":true,"data":{"anchor":"species","eyebrow":"Nature explorer","heading":"Meet the species","intro":"Search by name, or filter by group and habitat. Save entries to your field notebook to build your own guide.","mode":"all","count":12,"link":{"label":"","href":""}}},{"id":"b907b563-2811-4173-a25c-6b6bcb22f06b","type":"rich_text","visible":true,"data":{"anchor":"","eyebrow":"About this information","heading":"Reference entries and field observations","body":"<p>Everything in the explorer today is <strong>educational reference information</strong>, written to help people learn about species and habitats. The photographs are openly licensed images chosen to illustrate each entry; their captions say where they were taken.</p><p>ABC has not yet begun fieldwork. When participants in the proposed Nature Labs start recording wildlife, entries based on their records will be clearly marked as <strong>ABC field observations</strong>, and precise locations of sensitive species will never be published.</p><p>Conservation statuses follow the IUCN Red List and can change. Please check the Red List for the current assessment.</p>","width":"narrow","background":"white"}},{"id":"c3776aa4-74ff-4a14-a1e2-ff9c6032bc9c","type":"cta","visible":true,"data":{"anchor":"","eyebrow":"Get involved","heading":"Join us in protecting all life","text":"Volunteer, become a youth researcher, collaborate on research or explore a partnership with ABC.","primary":{"label":"Get involved","href":"/get-involved"},"secondary":{"label":"Contact us","href":"/contact"},"image":{"src":"/images/photos/youth-seedlings-group.jpg","alt":"A group of young people holding tree seedlings during a planting campaign","credit":"Atwijukirenaomi, CC BY-SA 4.0, via Wikimedia Commons"}}}]'::jsonb, '49daefb7-3edf-4887-a369-e03f557c5f3f'),
  ('published', '', '', 'citizen-science', 'Citizen Science', 'The citizen science observatory', 'How young people and communities can observe nature carefully, record what they see and turn it into knowledge.', '{"src":"/images/photos/akagera-waterbirds.jpg","alt":"Cormorants perched on small islands in calm water fringed by papyrus in Akagera National Park","credit":"John Cooke, CC BY 2.0, via Wikimedia Commons"}'::jsonb, true, '[{"id":"dce6cdef-c514-483f-aa2d-f557ec407457","type":"image_text","visible":true,"data":{"anchor":"","eyebrow":"What is citizen science?","heading":"Science that anyone can take part in","body":"<p>Citizen science is research carried out with the public. People observe the natural world around them, record what they find in a consistent way and share it, so that many small observations add up to something no single researcher could collect alone.</p><p>For ABC, it is also a way of learning. Looking closely at a bird, a plant or an insect, week after week, builds the attention and care that conservation depends on.</p>","image":{"src":"/images/photos/malachite-kingfisher.jpg","alt":"A malachite kingfisher with a bright orange breast and blue back perched on a reed","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"},"image_position":"right","variant":"light","badge":"","link":{"label":"","href":""}}},{"id":"da5e7a4d-786d-4a9d-a378-f695d267db95","type":"steps","visible":true,"data":{"anchor":"","eyebrow":"From a sighting to a record","heading":"How an observation becomes knowledge","intro":"","background":"white","style":"timeline","items":[{"icon":"eye","title":"Notice","text":"See or hear something, and take time to look properly.","activities":"","leads_to":""},{"icon":"notebook-pen","title":"Record","text":"Write down what, when and roughly where, in the same way each time.","activities":"","leads_to":""},{"icon":"search","title":"Check","text":"Confirm the identification with others before it is kept.","activities":"","leads_to":""},{"icon":"users","title":"Share","text":"Add it to the community''s shared record, with consent.","activities":"","leads_to":""},{"icon":"lightbulb","title":"Use","text":"Look for patterns and decide together what they mean.","activities":"","leads_to":""}]}},{"id":"03f70077-217b-4107-a585-34cf8a00a3cf","type":"projects","visible":true,"data":{"anchor":"projects","eyebrow":"Proposed activities","heading":"What communities could record","intro":"These activities are proposed for the pilot Nature Labs. None has started yet.","kind":"citizen_science","empty_text":"No citizen science activities have been published yet."}},{"id":"d7e82d7a-d71d-432a-a539-7052f5bccf52","type":"observations","visible":true,"data":{"anchor":"observations","eyebrow":"Community observations","heading":"Share what you have seen","intro":"Observations are reviewed by ABC before they appear here. We only ask for a general area, never a precise location.","closed_text":"Observation submissions are not open yet. They will open once the proposed Nature Labs begin and a team is in place to review each record. Until then, no observations are being collected or displayed."}},{"id":"921a101b-32a3-496b-ab03-d2a359f2b7a3","type":"faq","visible":true,"data":{"anchor":"","eyebrow":"Privacy and care","heading":"How observations will be handled","items":[{"question":"Will my observation be published straight away?","answer":"No. Every observation is reviewed by ABC first. Only approved observations, submitted with consent, are shown publicly."},{"question":"Do you publish where sensitive species were seen?","answer":"No. We ask only for a general area such as a district, and we do not collect or publish precise locations."},{"question":"Will my name appear?","answer":"Only if you ask to be credited. Contact details are never published, and the names of people under 18 are never shown."},{"question":"Can children take part?","answer":"Children are welcome to take part with a parent, guardian or teacher, who should submit the observation on their behalf."}]}},{"id":"ddf06789-5c4e-4759-a4fd-91d1a3ec76d1","type":"cta","visible":true,"data":{"anchor":"","eyebrow":"Get involved","heading":"Join us in protecting all life","text":"Volunteer, become a youth researcher, collaborate on research or explore a partnership with ABC.","primary":{"label":"Get involved","href":"/get-involved"},"secondary":{"label":"Contact us","href":"/contact"},"image":{"src":"/images/photos/youth-seedlings-group.jpg","alt":"A group of young people holding tree seedlings during a planting campaign","credit":"Atwijukirenaomi, CC BY-SA 4.0, via Wikimedia Commons"}}}]'::jsonb, '90393ca3-d505-4473-a35d-bffb3c2444fb'),
  ('published', '', '', 'research', 'Research & Insights', 'Community research', 'Locally led investigations into the questions that matter to communities, and what is learned from them.', '{"src":"/images/photos/rugezi-wetland.jpg","alt":"Channels of water winding through the green Rugezi wetland beneath rolling hills","credit":"Bisoke, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, true, '[{"id":"137b92f6-f689-4426-a589-019eae4f869e","type":"rich_text","visible":true,"data":{"anchor":"","eyebrow":"How ABC intends to do research","heading":"Questions that begin in the community","body":"<p>ABC''s proposed research is small in scale and practical in purpose. Young researchers, supported by mentors, investigate questions that their own communities want answered: about a wetland, a forest edge, a species people value or a change they have noticed.</p><p>The proposed six-month pilot aims to support two community research projects. They have not been chosen yet, because the questions belong to the communities who will take part.</p>","width":"narrow","background":"ivory"}},{"id":"0c761731-f0cc-4481-a528-bd7976430c79","type":"cards","visible":true,"data":{"anchor":"","eyebrow":"Principles","heading":"What good community research needs","intro":"","layout":"numbered","columns":"4","background":"white","items":[{"title":"Community questions first","text":"Research starts from what people living in a place want to understand.","icon":"leaf","image":null,"link":{"label":"","href":""}},{"title":"Sound methods","text":"Simple, repeatable methods, checked by mentors, so that results can be trusted.","icon":"leaf","image":null,"link":{"label":"","href":""}},{"title":"Consent and respect","text":"Local knowledge is recorded only with agreement, and credited to those who share it.","icon":"leaf","image":null,"link":{"label":"","href":""}},{"title":"Open sharing","text":"Findings go back to the community first, then are published openly.","icon":"leaf","image":null,"link":{"label":"","href":""}}]}},{"id":"6d99718e-ade4-4dde-aaac-e816d9d4df16","type":"projects","visible":true,"data":{"anchor":"projects","eyebrow":"Research projects","heading":"Current and completed research","intro":"","kind":"research","empty_text":"No research projects have begun. When the proposed pilot starts, each project will be listed here with its question, method, status and findings."}},{"id":"01401bcd-1faf-437d-a416-310512e4be05","type":"stories","visible":true,"data":{"anchor":"","eyebrow":"Insights","heading":"Reading on research and citizen science","intro":"","count":3,"featured_only":false,"link":{"label":"All stories","href":"/stories"}}},{"id":"3e6cc926-0bae-4976-af26-4c5e2d76095e","type":"cta","visible":true,"data":{"anchor":"","eyebrow":"Get involved","heading":"Join us in protecting all life","text":"Volunteer, become a youth researcher, collaborate on research or explore a partnership with ABC.","primary":{"label":"Get involved","href":"/get-involved"},"secondary":{"label":"Contact us","href":"/contact"},"image":{"src":"/images/photos/youth-seedlings-group.jpg","alt":"A group of young people holding tree seedlings during a planting campaign","credit":"Atwijukirenaomi, CC BY-SA 4.0, via Wikimedia Commons"}}}]'::jsonb, '09a8d505-f394-48b5-a78b-3e2d799dbd2d'),
  ('published', '', '', 'partners', 'Partners & Collaboration', 'Working together', 'ABC is at the proposal stage. This page sets out who we hope to work with, and will list partners once partnerships are confirmed.', '{"src":"/images/photos/community-planting-kivu.jpg","alt":"A young man planting a seedling on a hillside above Lake Kivu while others work nearby","credit":"Rogerirakoze, CC BY 4.0, via Wikimedia Commons"}'::jsonb, true, '[{"id":"7d49a3d0-f952-4600-a9ed-2cf812b3b1f8","type":"rich_text","visible":true,"data":{"anchor":"","eyebrow":"Where things stand","heading":"No confirmed partnerships yet","body":"<p>ABC is a proposed initiative and has not yet formed any formal partnerships. We think it is important to say so plainly.</p><p>Organisations will be named on this page only once a relationship has been agreed and they have given permission. Until then, we describe the kinds of collaboration we are looking for.</p>","width":"narrow","background":"ivory"}},{"id":"433436b7-86af-4a07-af53-fbefdb3dd0ef","type":"partners","visible":true,"data":{"anchor":"","eyebrow":"Confirmed partners","heading":"Our partners","intro":"","relationship":"confirmed","note":"","empty_text":"","link":{"label":"","href":""}}},{"id":"d3cb00ca-4226-4cba-a962-9f62a0e92662","type":"cards","visible":true,"data":{"anchor":"","eyebrow":"Ways to collaborate","heading":"Who we hope to work with","intro":"","layout":"icon","columns":"4","background":"white","items":[{"icon":"school","title":"Schools and educators","text":"Linking Nature Lab activities with classroom learning.","image":null,"link":{"label":"","href":""}},{"icon":"microscope","title":"Research institutions","text":"Mentoring young researchers and helping to keep methods sound.","image":null,"link":{"label":"","href":""}},{"icon":"trees","title":"Conservation organisations","text":"Sharing experience, sites and practical guidance.","image":null,"link":{"label":"","href":""}},{"icon":"hand-heart","title":"Funders and supporters","text":"Helping to bring the proposed pilot to life.","image":null,"link":{"label":"","href":""}}]}},{"id":"d35c9b60-bbed-41f0-a8ea-1a787739d778","type":"cta","visible":true,"data":{"anchor":"","eyebrow":"Start a conversation","heading":"Interested in working with ABC?","text":"Tell us about your organisation and what you have in mind.","primary":{"label":"Contact us","href":"/contact"},"secondary":{"label":"Get involved","href":"/get-involved"},"image":{"src":"/images/photos/community-wetland-planting.jpg","alt":"Two people planting vegetation among green plants as part of wetland protection in Rwanda","credit":"Germain92, CC BY-SA 4.0, via Wikimedia Commons"}}}]'::jsonb, '9f079adb-d019-4b0b-a548-aec3a75b2dc3'),
  ('published', '', '', 'get-involved', 'Get Involved', 'Take part', 'Join ABC as a volunteer, youth researcher, research collaborator or institutional partner.', '{"src":"/images/photos/youth-seedlings-group.jpg","alt":"A group of young people holding tree seedlings during a planting campaign","credit":"Atwijukirenaomi, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, true, '[{"id":"d78fe0b8-98ae-41e8-ac2f-1ff08a7edcf0","type":"cards","visible":true,"data":{"anchor":"","eyebrow":"Ways to take part","heading":"Find your place in ABC","intro":"ABC is preparing its first proposed pilot. Expressions of interest help us plan and build the right team.","layout":"icon","columns":"3","background":"ivory","items":[{"icon":"hand-heart","title":"Volunteer opportunities","text":"Support nature learning sessions, events, logistics, photography or communications.","image":null,"link":{"label":"Apply to volunteer","href":"#apply"}},{"icon":"sprout","title":"Youth participation","text":"Young people can take part in learning activities or train as youth researchers.","image":null,"link":{"label":"Express interest","href":"#apply"}},{"icon":"microscope","title":"Research collaboration","text":"Researchers and students can co-design community research and mentor young people.","image":null,"link":{"label":"Collaborate","href":"#apply"}},{"icon":"handshake","title":"Institutional partnerships","text":"Organisations can explore partnerships that strengthen youth-led conservation.","image":null,"link":{"label":"Start a conversation","href":"/contact"}},{"icon":"users","title":"Community engagement","text":"Community groups can help shape where and how Nature Labs could work.","image":null,"link":{"label":"Get in touch","href":"#apply"}},{"icon":"megaphone","title":"Share the story","text":"Help more people learn about ABC by sharing our stories and updates.","image":null,"link":{"label":"Read stories","href":"/stories"}}]}},{"id":"14a4cf0a-3aac-45ba-a286-77b2d0d634b2","type":"form","visible":true,"data":{"anchor":"apply","eyebrow":"Express your interest","heading":"Tell us how you would like to be involved","intro":"We read every submission. ABC is at an early stage, so we will contact you as suitable opportunities become available.","form":"volunteer","image":{"src":"/images/photos/youth-tree-planting.jpg","alt":"Young people kneeling together to plant seedlings in Rwanda","credit":"Germain92, CC BY-SA 4.0, via Wikimedia Commons"}}},{"id":"9802b6b4-9904-4344-aea9-322c4324a12c","type":"faq","visible":true,"data":{"anchor":"","eyebrow":"Questions","heading":"Before you apply","items":[{"question":"Is ABC recruiting right now?","answer":"ABC is preparing a proposed pilot. Expressions of interest help us plan; we will contact you when suitable opportunities open."},{"question":"Do I need scientific experience?","answer":"No. Curiosity and commitment matter most. Training would be part of every ABC activity."},{"question":"How will my information be used?","answer":"Only to respond to your submission. Please see our privacy policy for details."}]}}]'::jsonb, '6fea533c-3872-48ec-a467-0424d8e27324'),
  ('published', '', '', 'contact', 'Contact', 'Get in touch', 'Questions, ideas or collaboration proposals: we would be glad to hear from you.', '{"src":"/images/photos/lake-kivu.jpg","alt":"Forested shoreline and calm water of Lake Kivu, Rwanda","credit":"Muhirehussein12, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, true, '[{"id":"3e138acf-dde1-413f-a396-83475419e247","type":"contact_details","visible":true,"data":{"anchor":"","eyebrow":"Contact details","heading":"Ways to reach us","intro":"","show_social":true}},{"id":"2ccc716d-347a-41dd-a449-79f5b29936f5","type":"form","visible":true,"data":{"anchor":"message","eyebrow":"Send a message","heading":"How can we help?","intro":"Use this form for questions, partnership ideas, research collaboration or media enquiries.","form":"contact","image":null}}]'::jsonb, '85e495ec-a905-4c1c-a19e-9634408d7b34'),
  ('published', '', '', 'privacy', 'Privacy Policy', 'Information', 'How ABC collects, uses and protects personal information submitted through this website.', null, true, '[{"id":"ae21df2b-68dc-445b-a1c0-1d93600fda93","type":"rich_text","visible":true,"data":{"anchor":"","eyebrow":"","heading":"","width":"narrow","background":"white","body":"<p>This policy explains how ABC (Alliance for Biodiversity and Conservation) handles personal information submitted through this website. Please review and adapt it with appropriate advice before relying on it.</p>\n<h2>Information we collect</h2>\n<p>We only collect information that you choose to send us through our forms:</p>\n<ul><li><strong>Contact form:</strong> your name, email address, optional organisation, subject and message.</li><li><strong>Involvement form:</strong> your name, email address, optional phone number and location, your area of interest, optional organisation, availability, experience and message.</li><li><strong>Newsletter:</strong> your email address.</li></ul>\n<p>To protect the forms from abuse, we store a one-way, anonymised hash of the network address used to submit a form for a short period. We do not store your network address itself.</p>\n<h2>How we use your information</h2>\n<p>We use your information only to respond to your enquiry, to consider your expression of interest, or to send you the updates you requested. We do not sell your information or share it for marketing purposes.</p>\n<h2>Where information is stored</h2>\n<p>Submissions are stored securely in our database, hosted by Supabase, and can only be accessed by authorised ABC administrators.</p>\n<h2>How long we keep it</h2>\n<p>We keep submissions only for as long as needed to respond and to manage ongoing involvement, and we delete them when they are no longer required.</p>\n<h2>Your rights</h2>\n<p>You can ask us to access, correct or delete the information you have sent us, or to remove you from our updates, by contacting us through our contact page.</p>\n<h2>Cookies</h2>\n<p>The public website does not use advertising or tracking cookies. Essential cookies are used only in the administrator area to keep authorised users signed in. A setting to reduce motion is stored in your browser if you choose to use it.</p>\n<h2>Changes to this policy</h2>\n<p>We may update this policy as ABC develops. The current version will always be available on this page.</p>"}}]'::jsonb, '4753ba60-2a86-49d0-aae1-7aa849d05fa8')
insert into public.programmes (id, status, is_published, is_featured, seo_title, seo_description, slug, title, summary, icon, category, sort_order, cover_image, description) values
  ('57e95388-f5b6-47d8-aa5f-5410c92de110', 'proposed', true, true, '', '', 'abc-learning', 'ABC Learning', 'Nature learning for children and young people, connecting them with the species and ecosystems around them.', 'book-open', 'Learning', 1, '{"src":"/images/photos/youth-seedlings-group.jpg","alt":"A group of young people holding tree seedlings during a planting campaign","credit":"Atwijukirenaomi, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, '<p>ABC Learning is the proposed programme area for environmental education. It would offer children and young people regular, hands-on opportunities to explore nature, learn to identify local species and understand how ecosystems work.</p><h2>What it could include</h2><ul><li>Guided nature walks and outdoor learning sessions</li><li>Species identification and field skills</li><li>Learning resources developed with educators</li><li>Activities linked to the proposed Community Nature Labs</li></ul><h2>Current status</h2><p>ABC Learning is a proposed programme area. Its first activities are planned as part of the proposed six-month Rwanda pilot.</p>'),
  ('f5272d94-49dc-48c4-aac6-f18c9b4a508c', 'proposed', true, true, '', '', 'abc-science', 'ABC Science', 'Citizen science and community research that generate useful ecological knowledge.', 'microscope', 'Research', 2, '{"src":"/images/photos/akagera-waterbirds.jpg","alt":"Cormorants perched on small islands in calm water fringed by papyrus in Akagera National Park","credit":"John Cooke, CC BY 2.0, via Wikimedia Commons"}'::jsonb, '<p>ABC Science is the proposed programme area for citizen science and community research. It would equip young people and communities to observe and record biodiversity systematically and to investigate local ecological questions.</p><h2>What it could include</h2><ul><li>Structured biodiversity monitoring</li><li>Community research projects with mentors</li><li>Training in data quality and research ethics</li><li>Sharing data and findings with conservation stakeholders</li></ul><h2>Current status</h2><p>ABC Science is a proposed programme area. The pilot proposes two community research projects.</p>'),
  ('fbd3bc84-56a1-4594-abe2-ac5cd4a9315c', 'proposed', true, true, '', '', 'abc-action', 'ABC Action', 'Community-owned conservation action guided by evidence and local knowledge.', 'trees', 'Conservation', 3, '{"src":"/images/photos/community-planting-kivu.jpg","alt":"A young man planting a seedling on a hillside above Lake Kivu while others work nearby","credit":"Rogerirakoze, CC BY 4.0, via Wikimedia Commons"}'::jsonb, '<p>ABC Action is the proposed programme area for practical conservation. It would help communities turn what they learn into meaningful action for the species and habitats around them.</p><h2>What it could include</h2><ul><li>Habitat restoration and native planting</li><li>Awareness and community engagement activities</li><li>Collaboration with conservation authorities and organisations</li></ul><h2>Current status</h2><p>ABC Action is a proposed long-term programme area.</p>'),
  ('aa18336a-4ffd-44ba-a6f1-211277748012', 'proposed', true, true, '', '', 'abc-fellows', 'ABC Fellows', 'Developing the next generation of youth conservation leaders and researchers.', 'graduation-cap', 'Leadership', 4, '{"src":"/images/photos/youth-tree-planting.jpg","alt":"Young people kneeling together to plant seedlings in Rwanda","credit":"Germain92, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, '<p>ABC Fellows is the proposed programme area for youth leadership. It would support committed young people to develop as conservation researchers, educators and leaders through training, mentoring and practical experience.</p><h2>What it could include</h2><ul><li>Training as youth researchers and facilitators</li><li>Mentoring from experienced practitioners</li><li>Opportunities to lead projects and share findings</li></ul><h2>Current status</h2><p>ABC Fellows is a proposed long-term programme area. The pilot proposes training a first group of youth researchers.</p>'),
  ('dc60832c-0109-425c-a188-cd34120c2c34', 'proposed', true, true, '', '', 'abc-network', 'ABC Network', 'A growing network connecting young people, communities, researchers and organisations.', 'network', 'Network', 5, '{"src":"/images/photos/rugezi-wetland.jpg","alt":"Channels of water winding through the green Rugezi wetland beneath rolling hills","credit":"Bisoke, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, '<p>ABC Network is the proposed programme area for connection and collaboration. Over time, it would link Nature Labs, young people, communities, researchers and organisations so that knowledge and experience can be shared widely.</p><h2>What it could include</h2><ul><li>Exchanges between Nature Lab communities</li><li>Collaboration with researchers and institutions</li><li>Shared learning, events and stories</li></ul><h2>Current status</h2><p>ABC Network is a proposed long-term programme area.</p>')
insert into public.article_categories (id, name, slug, description, sort_order) values
  ('425295a6-69e5-4316-a3d8-0c9e38537b9e', 'Articles', 'articles', 'Explainers and perspectives on biodiversity and conservation.', 1),
  ('cb8de2fb-db1b-4cab-a2ce-50d373e89fd3', 'Research Updates', 'research-updates', 'Progress and findings from ABC research.', 2),
  ('fe5e4bb3-0458-40e3-aa7d-fdeb734482eb', 'Field Notes', 'field-notes', 'Observations from time spent in nature.', 3),
