insert into public.articles (id, slug, title, excerpt, content, featured_image, gallery, video_url, category_id, author_name, status, published_at, is_featured, seo_title, seo_description) values
  ('7ecae30c-1ac7-409c-a7ee-4644b7163d44', 'introducing-abc', 'Introducing the Alliance for Biodiversity and Conservation', 'ABC is a proposed youth-led initiative that aims to connect young people and communities with biodiversity through learning, citizen science, research and action.', '"<p>Across Africa, young people grow up alongside extraordinary biodiversity: wetlands alive with cranes, forests full of primates and birdsong, and landscapes shaped by people and wildlife together. Yet many have few chances to explore that biodiversity, study it or help decide its future.</p><p>ABC, the Alliance for Biodiversity and Conservation, is a proposed youth-led initiative created to change that. Our purpose is to empower young people and communities through environmental learning, citizen science, research and collective action to protect biodiversity and sustain healthy ecosystems.</p><h2>Five connected activities</h2><p>Our approach brings together Nature Learning, Citizen Science, Community Research, Conservation Action and Conservation Storytelling. Each activity builds on the last, following a simple pathway: learn, observe, investigate, understand, act and share.</p><h2>Starting with a pilot</h2><p>ABC proposes to begin with a six-month pilot of Community Nature Learning and Citizen Science Labs at two sites in Rwanda. The pilot is designed to test the model carefully, learn from participants and build the evidence needed to grow responsibly.</p><blockquote><p>Together for All Life.</p></blockquote><p>We will share progress openly on this website. If you would like to be part of this work, please visit our Get Involved page.</p>"'::jsonb, '{"src":"/images/photos/elephants-family.jpg","alt":"An African bush elephant walking along a track through green bush with her young calf","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, '[]'::jsonb, '', '0c9ff543-97e8-4e13-a504-eecbe3d37bcb', 'ABC', 'published', '2026-11-15T09:00:00.000Z', true, '', ''),
  ('ab67c016-9a57-49a6-acee-381e1ee05d1e', 'what-is-a-nature-lab', 'What is a Community Nature Lab?', 'An introduction to ABC''s proposed model for community-based learning and citizen science, and the two-site pilot planned for Rwanda.', '"<p>A Community Nature Learning and Citizen Science Lab, or Nature Lab, is ABC''s proposed model for bringing people and biodiversity together in everyday life.</p><h2>More than a classroom</h2><p>A Nature Lab is not primarily a building. It combines a local base, a nearby natural site such as a wetland, forest edge or school garden, simple field equipment, trained facilitators and a regular programme of activities that the community helps to shape.</p><h2>What happens in a Nature Lab?</h2><ul><li><strong>Learning:</strong> children and young people explore local species and habitats.</li><li><strong>Observation:</strong> participants record what they see using simple, consistent methods.</li><li><strong>Research:</strong> youth researchers investigate questions that matter locally.</li><li><strong>Action:</strong> communities plan practical responses based on what they learn.</li><li><strong>Sharing:</strong> findings and stories are shared with the community and beyond.</li></ul><h2>The proposed Rwanda pilot</h2><p>ABC proposes to test the model through a six-month pilot at two sites in Rwanda. The pilot sites have not yet been established; they will be selected together with communities and relevant institutions.</p>"'::jsonb, '{"src":"/images/photos/youth-tree-planting.jpg","alt":"Young people kneeling together to plant seedlings in Rwanda","credit":"Germain92, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, '[{"src":"/images/photos/youth-seedlings-group.jpg","alt":"A group of young people holding tree seedlings during a planting campaign","credit":"Atwijukirenaomi, CC BY-SA 4.0, via Wikimedia Commons"},{"src":"/images/photos/community-planting-kivu.jpg","alt":"A young man planting a seedling on a hillside above Lake Kivu while others work nearby","credit":"Rogerirakoze, CC BY 4.0, via Wikimedia Commons"},{"src":"/images/photos/community-wetland-planting.jpg","alt":"Two people planting vegetation among green plants as part of wetland protection in Rwanda","credit":"Germain92, CC BY-SA 4.0, via Wikimedia Commons"}]'::jsonb, '', '425295a6-69e5-4316-a3d8-0c9e38537b9e', 'ABC', 'published', '2026-11-15T09:00:00.000Z', false, '', ''),
  ('8cd25164-a185-4774-a3c4-8a3cba7ad13c', 'why-citizen-science-matters', 'Why citizen science matters for biodiversity', 'When communities observe and record nature systematically, they help fill knowledge gaps and strengthen local conservation.', '"<p>Much of what we know about how species and ecosystems are changing comes from careful, repeated observation. Professional scientists cannot be everywhere, which is why citizen science, the participation of members of the public in scientific research, has become so valuable.</p><h2>Filling knowledge gaps</h2><p>Many places rich in biodiversity have relatively few long-term records. Observations gathered consistently by local people can help reveal patterns, such as when birds arrive, how wetland vegetation changes through the seasons or where important species are found.</p><h2>Building connection and skills</h2><p>Citizen science is also about people. Learning to identify species, follow a method and record data builds skills and confidence. It turns everyday surroundings into places of discovery.</p><h2>How ABC plans to use it</h2><p>Citizen science is one of ABC''s five interconnected activities. In the proposed Nature Labs, participants would learn simple recording methods and, where appropriate, contribute observations to wider biodiversity databases.</p>"'::jsonb, '{"src":"/images/photos/grey-crowned-crane.jpg","alt":"A Grey Crowned Crane with its golden crest walking at the edge of shallow water","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, '[]'::jsonb, '', '425295a6-69e5-4316-a3d8-0c9e38537b9e', 'ABC', 'published', '2026-11-15T09:00:00.000Z', false, '', '')
