insert into public.ecosystems (id, slug, name, zone, elevation, summary, description, processes, example_places, photo, sort_order, is_published) values
  ('31fd2fd7-bc45-4867-a34a-5c6f01e4f16f', 'great-lake-shores', 'Lake Kivu and its shores', 'lake', 'About 1,460 m', 'One of Africa''s Great Lakes, edged by steep, cultivated and forested slopes.', '<p>Lake Kivu lies along Rwanda''s western border in the Albertine Rift. Its shoreline mixes fishing communities, farmland, islands and patches of remaining woodland.</p><p>Lakeshores are meeting places between water and land. Shoreline vegetation holds soil in place, shelters young fish and provides nesting and feeding sites for waterbirds.</p>', 'Nutrient cycling between land and water
