  ('b796645d-a82e-448d-a3aa-b7d5e2999cd5', 'Birds', 'birds', 'From wetland cranes to forest turacos.', 'bird', 1),
  ('52068fdb-07a1-4f2b-a94a-8703cc687403', 'Mammals', 'mammals', 'Primates, grazers and other mammals.', 'footprints', 2),
