insert into public.species (slug, common_name, scientific_name, local_name, category_id, ecosystem_id, photo, summary, description, habitat, ecological_role, conservation_status, conservation_notes, is_featured, id, entry_type, status, sources, sort_order) values
  ('grey-crowned-crane', 'Grey Crowned Crane', 'Balearica regulorum', 'Umusambi', 'b796645d-a82e-448d-a3aa-b7d5e2999cd5', '56b998ad-6b6a-409d-a465-aff53fde56f5', '{"src":"/images/photos/grey-crowned-crane.jpg","alt":"A Grey Crowned Crane with its golden crest walking at the edge of shallow water","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, 'A tall wetland bird with a crown of stiff golden feathers, known for its dancing displays.', '<p>The Grey Crowned Crane is one of the most recognisable birds of eastern and southern Africa. Pairs perform elaborate dances of bowing, jumping and wing-spreading, and they nest in wetlands, hiding their eggs among tall vegetation.</p><p>Unlike most cranes, it can roost in trees, using a long hind toe to grip branches.</p>', 'Marshes, flooded grassland and farmland close to water. It needs undisturbed wetland to nest.', 'Feeds on seeds, insects and other small animals. Because it depends on healthy marshes to breed, its presence says something about the condition of a wetland.', 'EN', 'The main pressures are the loss and drainage of wetlands and the illegal capture of birds and eggs.', true, 'ab86c3a5-e7de-49f5-a3c3-881d802de51d', 'reference', 'published', '[{"label":"IUCN Red List of Threatened Species","url":"https://www.iucnredlist.org"}]'::jsonb, 1),
  ('mountain-gorilla', 'Mountain gorilla', 'Gorilla beringei beringei', 'Ingagi', '52068fdb-07a1-4f2b-a94a-8703cc687403', '0ed5e504-cb66-4814-ac54-e38c17cd8a8c', '{"src":"/images/photos/mountain-gorilla.jpg","alt":"A mountain gorilla sitting among green leaves in Volcanoes National Park, Rwanda","credit":"Emmanuel Kwizera, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, 'A great ape of high mountain forest, living in close family groups led by a silverback.', '<p>Mountain gorillas live only in two areas: the Virunga volcanoes shared by Rwanda, Uganda and the Democratic Republic of the Congo, and Bwindi Impenetrable National Park in Uganda.</p><p>They spend most of the day feeding on leaves, stems and shoots, and build a fresh nest of vegetation to sleep in each night.</p>', 'Montane and bamboo forest on the slopes of the Virunga volcanoes.', 'As large plant-eaters, gorillas open up vegetation as they feed and move, creating space and light for other plants, and they spread seeds in their dung.', 'EN', 'Published censuses have recorded a slow increase to just over 1,000 individuals, following decades of intensive protection. The population remains small and confined to two areas.', true, '8c722855-4919-4865-a67e-2b0d6268000d', 'reference', 'published', '[{"label":"IUCN Red List of Threatened Species","url":"https://www.iucnredlist.org"}]'::jsonb, 2),
  ('african-savanna-elephant', 'African savanna elephant', 'Loxodonta africana', 'Inzovu', '52068fdb-07a1-4f2b-a94a-8703cc687403', 'ba18a894-a7ca-4ac4-a0f6-6cfc0c6f13fc', '{"src":"/images/photos/elephants-family.jpg","alt":"An African bush elephant walking along a track through green bush with her young calf","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, 'The largest living land animal, moving in family herds led by older females.', '<p>Savanna elephants live in herds of related females and their young, guided by a matriarch whose memory of water and feeding places can matter greatly in dry years.</p><p>They communicate with touch, scent and low rumbles, some of which travel long distances.</p>', 'Savanna, woodland and wetland edges.', 'Often described as ecosystem engineers. By pushing over trees, digging for water and carrying seeds long distances, elephants reshape habitats that many other species use.', 'EN', 'Threatened by poaching for ivory and by the loss and fragmentation of habitat.', true, '62f22738-32f8-48c8-a930-5060fd5fc560', 'reference', 'published', '[{"label":"IUCN Red List of Threatened Species","url":"https://www.iucnredlist.org"}]'::jsonb, 3),
  ('eastern-chimpanzee', 'Eastern chimpanzee', 'Pan troglodytes schweinfurthii', 'Impundu', '52068fdb-07a1-4f2b-a94a-8703cc687403', '0ed5e504-cb66-4814-ac54-e38c17cd8a8c', '{"src":"/images/photos/chimpanzee.jpg","alt":"An eastern chimpanzee sitting among forest vegetation","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, 'A highly social great ape that uses tools and lives in large, shifting communities.', '<p>Chimpanzees live in communities whose members split into smaller parties and come back together through the day. They use sticks, leaves and stones as tools, and different communities have different habits.</p><p>In Rwanda, chimpanzees live in mountain forest.</p>', 'Forest, from lowland rainforest to high montane forest.', 'Chimpanzees eat a great deal of fruit and carry the seeds far from the parent tree, helping forests to regenerate.', 'EN', 'Threatened by forest loss, hunting and disease.', false, '68414516-004d-4b66-a111-d23eed7c2f3e', 'reference', 'published', '[{"label":"IUCN Red List of Threatened Species","url":"https://www.iucnredlist.org"}]'::jsonb, 4),
  ('great-blue-turaco', 'Great blue turaco', 'Corythaeola cristata', '', 'b796645d-a82e-448d-a3aa-b7d5e2999cd5', '0ed5e504-cb66-4814-ac54-e38c17cd8a8c', '{"src":"/images/photos/great-blue-turaco.jpg","alt":"A great blue turaco perched on a branch, showing its blue-green plumage and dark crest","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, 'The largest of the turacos, a blue-green forest bird with a tall dark crest.', '<p>Great blue turacos move through the forest canopy in small groups, running and bounding along branches more often than they fly. Their deep, rolling calls carry a long way.</p>', 'The canopy of rainforest and montane forest, and tall trees along rivers.', 'Feeds mainly on fruit and leaves, and spreads the seeds of many forest trees.', 'LC', 'Widespread, but dependent on forest with large fruiting trees.', false, '378c4454-1aaf-4ba4-aa39-785cbb53c75c', 'reference', 'published', '[{"label":"IUCN Red List of Threatened Species","url":"https://www.iucnredlist.org"}]'::jsonb, 5),
  ('hippopotamus', 'Hippopotamus', 'Hippopotamus amphibius', 'Imvubu', '52068fdb-07a1-4f2b-a94a-8703cc687403', 'ba18a894-a7ca-4ac4-a0f6-6cfc0c6f13fc', '{"src":"/images/photos/hippopotamus.jpg","alt":"A hippopotamus partly submerged in calm water","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, 'A very large, semi-aquatic mammal that rests in water by day and grazes on land at night.', '<p>Hippos spend the day in lakes and rivers, which keeps their skin cool and moist. At dusk they leave the water and walk to grazing areas, returning before dawn.</p>', 'Lakes, rivers and swamps with grassland nearby.', 'By grazing on land and resting in water, hippos carry nutrients from grassland into lakes and rivers, where they feed aquatic life.', 'VU', 'Threatened by habitat loss and hunting.', false, '5e13cd44-e2b6-4b34-a0c1-690c7987ee0c', 'reference', 'published', '[{"label":"IUCN Red List of Threatened Species","url":"https://www.iucnredlist.org"}]'::jsonb, 6),
  ('malachite-kingfisher', 'Malachite kingfisher', 'Corythornis cristatus', '', 'b796645d-a82e-448d-a3aa-b7d5e2999cd5', '56b998ad-6b6a-409d-a465-aff53fde56f5', '{"src":"/images/photos/malachite-kingfisher.jpg","alt":"A malachite kingfisher with a bright orange breast and blue back perched on a reed","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, 'A tiny, jewel-bright kingfisher of reeds and quiet water.', '<p>The malachite kingfisher perches low over the water on reeds and stems, then dives for its prey. It is small enough to overlook, but its blue back and orange underside are unmistakable once seen.</p>', 'Reeds and vegetation beside slow rivers, ponds, lakes and marshes.', 'A predator of small fish, tadpoles and aquatic insects, and an easy species for new observers to learn at a wetland.', 'LC', 'Widespread across Africa south of the Sahara where there is suitable water.', true, '121ba706-40a5-40d6-a663-ebde585610de', 'reference', 'published', '[{"label":"IUCN Red List of Threatened Species","url":"https://www.iucnredlist.org"}]'::jsonb, 7),
  ('african-monarch', 'African monarch', 'Danaus chrysippus', '', 'c2ce82b4-ea66-4a84-ac14-01dcdf31eedc', '00e5de44-f3d9-4594-ab52-e78c58ab768c', '{"src":"/images/photos/african-monarch.jpg","alt":"An African monarch butterfly with orange, black and white wings resting on a plant","credit":"Charles J. Sharp, CC BY-SA 4.0, via Wikimedia Commons"}'::jsonb, 'A common orange butterfly of gardens and open country, protected by chemicals from its food plants.', '<p>The African monarch, also called the plain tiger, is one of the most familiar butterflies in Africa. Its caterpillars feed on milkweeds and store the plants'' toxins, which makes both caterpillar and adult distasteful to many predators.</p><p>Its bold orange, black and white pattern is a warning, and several other butterflies have evolved to look like it.</p>', 'Open, sunny places: gardens, fields, roadsides and grassland.', 'Adults visit flowers for nectar and can carry pollen between them. Caterpillars and adults are part of the food web for the predators that tolerate them.', '', 'Widespread and common. Check the IUCN Red List for its current assessment.', false, 'e6204238-8fcf-4488-a563-4b50648b4250', 'reference', 'published', '[{"label":"IUCN Red List of Threatened Species","url":"https://www.iucnredlist.org"}]'::jsonb, 8)
